// Package cli implements the command dispatcher for direnv.
package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Version is the direnv version reported by the binary.
const Version = "2.37.1"

// Colors used for logger output.
const (
	ansiReset = "\x1b[0m"
	ansiRed   = "\x1b[31m"
)

// Shell names known to export/hook commands.
var exportShells = []string{
	"bash",
	"elvish",
	"fish",
	"gha",
	"gzenv",
	"json",
	"murex",
	"pwsh",
	"systemd",
	"tcsh",
	"vim",
	"zsh",
}

// logErr prints a red "direnv: error <msg>" line to stderr.
func logErr(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "%sdirenv: error %s%s\n", ansiRed, fmt.Sprintf(format, args...), ansiReset)
}

// logMsg prints "direnv: <msg>" prefixed with a color prefix (red for error,
// reset otherwise) to stderr. This mirrors the format used by the binary.
func logMsg(color, format string, args ...interface{}) {
	switch color {
	case "error":
		fmt.Fprintf(os.Stderr, "%sdirenv: %s%s\n", ansiRed, fmt.Sprintf(format, args...), ansiReset)
	default:
		fmt.Fprintf(os.Stderr, "%sdirenv: %s\n", ansiReset, fmt.Sprintf(format, args...))
	}
}

// Run dispatches the requested sub-command.
func Run(argv []string) int {
	if len(argv) < 2 {
		HelpCmd(argv, false)
		return 0
	}

	cmd := argv[1]
	args := argv[2:]

	switch cmd {
	case "version":
		return VersionCmd(args)
	case "help":
		return HelpCmd(argv, len(args) > 0)
	case "status":
		return StatusCmd(args)
	case "stdlib":
		return StdlibCmd(args)
	case "hook":
		return HookCmd(args)
	case "log":
		return LogCmd(args)
	case "export":
		return ExportCmd(args)
	case "exec":
		return ExecCmd(args)
	case "allow", "permit", "grant":
		return AllowCmd(args)
	case "block", "deny", "disallow", "revoke":
		return BlockCmd(args)
	case "edit":
		return EditCmd(args)
	case "fetchurl":
		return FetchurlCmd(args)
	case "prune":
		return PruneCmd(args)
	case "reload":
		return ReloadCmd(args)
	case "apply_dump":
		return ApplyDumpCmd(args)
	case "show_dump":
		return ShowDumpCmd(args)
	case "check-required":
		return CheckRequiredCmd(args)
	case "dotenv":
		return DotenvCmd(args)
	case "dump":
		return DumpCmd(args)
	case "watch":
		return WatchCmd(args)
	case "watch-dir":
		return WatchDirCmd(args)
	case "watch-list":
		return WatchListCmd(args)
	case "watch-print":
		return WatchPrintCmd(args)
	case "current":
		return CurrentCmd(args)
	default:
		logErr("command %q not found", argv[0]+" "+cmd)
		return 1
	}
}

// SelfPath returns the absolute path of the running direnv executable.
func SelfPath() string {
	p, err := os.Executable()
	if err != nil {
		if len(os.Args) > 0 {
			return os.Args[0]
		}
		return "direnv"
	}
	r, err := filepath.EvalSymlinks(p)
	if err != nil {
		return p
	}
	return r
}

// ConfigDir returns the configuration directory for direnv.
// It checks DIRENV_CONFIG, then XDG_CONFIG_HOME, then HOME.
// Returns empty string if no directory can be determined.
func ConfigDir() (string, error) {
	if v := os.Getenv("DIRENV_CONFIG"); v != "" {
		return v, nil
	}
	if v := os.Getenv("XDG_CONFIG_HOME"); v != "" {
		return filepath.Join(v, "direnv"), nil
	}
	if v := os.Getenv("HOME"); v != "" {
		return filepath.Join(v, ".config", "direnv"), nil
	}
	return "", fmt.Errorf("couldn't find a configuration directory for direnv")
}

// DataDir returns the data directory for direnv (for allow/deny files).
func DataDir() (string, error) {
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return filepath.Join(v, "direnv"), nil
	}
	if v := os.Getenv("HOME"); v != "" {
		return filepath.Join(v, ".local", "share", "direnv"), nil
	}
	return "", fmt.Errorf("couldn't find a data directory for direnv")
}

// ShellIsKnown reports whether the given shell name is recognized by export.
func ShellIsKnown(name string) bool {
	for _, s := range exportShells {
		if s == name {
			return true
		}
	}
	return false
}

// StringsAny reports whether s equals any of the vs.
func StringsAny(s string, vs ...string) bool {
	for _, v := range vs {
		if s == v {
			return true
		}
	}
	return false
}

// _ keeps strings import referenced in case it is needed later.
var _ = strings.TrimSpace
EOF

