	currParts, ok := parseSemver("v" + Version)
	if !ok {
		logErr("%s is not a valid semver version", "v"+Version)
		return 1
	}
	if compareSemver(currParts, wantParts) < 0 {
		logErr("current version v%s is older than the desired version v%s", Version, trimV(want))
		return 1
	}
	return 0
}

func trimV(s string) string {
	return strings.TrimPrefix(s, "v")
}

// parseSemver parses a version string like vX.Y.Z (optionally -prerelease).
// It returns {major, minor, patch} and an ok flag.
func parseSemver(v string) ([3]int, bool) {
	s := strings.TrimPrefix(v, "v")
	// Strip prerelease/metadata
	if i := strings.IndexAny(s, "-+"); i >= 0 {
		s = s[:i]
	}
	parts := strings.Split(s, ".")
	if len(parts) == 0 || len(parts) > 3 {
		return [3]int{}, false
	}
	var out [3]int
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 {
			return [3]int{}, false
		}
		out[i] = n
	}
	return out, true
}

func compareSemver(a, b [3]int) int {
	for i := 0; i < 3; i++ {
		if a[i] != b[i] {
			if a[i] < b[i] {
				return -1
			}
			return 1
		}
	}
	return 0
}

