// randomShellList returns the export shells in a random order, like Go's
// map iteration order. This matches the binary's help output which prints
// shells in non-deterministic order.
func randomShellList() string {
	shells := make([]string, len(exportShells))
	copy(shells, exportShells)
	rand.Shuffle(len(shells), func(i, j int) { shells[i], shells[j] = shells[j], shells[i] })
	return "Supported SHELL values are: [" + strings.Join(shells, ", ") + "]"
}

