	buf.WriteString("------------------\n")
	for _, e := range helpEntries() {
		if e.private && !private {
			continue
		}
		prefix := ""
		if e.private {
			prefix = "*"
		}
		if e.args != "" {
			fmt.Fprintf(&buf, "%s%s %s:\n", prefix, e.name, e.args)
		} else {
			fmt.Fprintf(&buf, "%s%s:\n", prefix, e.name)
		}
		if len(e.aliases) > 0 {
