// ----- allow / block -----

func resolveRCPath(given string) (string, error) {
	var p string
	if given != "" {
		fi, err := os.Lstat(given)
		if err != nil {
			return "", err
		}
		if fi.IsDir() {
			// directory - look for .envrc or .env
			env1 := filepath.Join(given, ".envrc")
			env2 := filepath.Join(given, ".env")
			if _, err := os.Stat(env1); err == nil {
				p = env1
			} else if _, err := os.Stat(env2); err == nil {
				p = env2
			} else {
				return "", fmt.Errorf(".envrc file not found")
			}
		} else {
			p = given
		}
	} else {
		cwd, err := os.Getwd()
		if err != nil {
			return "", err
		}
		p = findRCUp(cwd)
		if p == "" {
			return "", fmt.Errorf(".envrc file not found")
		}
	}
	return filepath.Abs(p)
}

func findRCUp(dir string) string {
	for {
		p := filepath.Join(dir, ".envrc")
		if _, err := os.Stat(p); err == nil {
			return p
		}
		p = filepath.Join(dir, ".env")
		if _, err := os.Stat(p); err == nil {
			return p
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

func AllowCmd(args []string) int {
	given := ""
