		for _, kv := range pairs {
			m[kv.k] = kv.v
		}
		b, _ := json.MarshalIndent(m, "", "  ")
		fmt.Println(string(b))
	default:
		logErr("unknown target shell '%s'", shell)
		return 1
	}
	return 0
