// randomShellList returns the export shells in a random order, like Go's
// map iteration order. This matches the binary's help output which prints
// shells in non-deterministic order.
func randomShellList() string {
	shells := make([]string, len(exportShells))
	copy(shells, exportShells)
	rand.Shuffle(len(shells), func(i, j int) { shells[i], shells[j] = shells[j], shells[i] })
	return "Supported SHELL values are: [" + strings.Join(shells, ", ") + "]"
}

func HelpCmd(argv []string, private bool) int {
	var buf bytes.Buffer
	fmt.Fprintf(&buf, "direnv v%s\n", Version)
	buf.WriteString("Usage: direnv COMMAND [...ARGS]\n")
	buf.WriteString("\n")
	buf.WriteString("Available commands\n")
	buf.WriteString("------------------\n")
	for _, e := range helpEntries() {
		if e.private && !private {
			continue
		}
		prefix := ""
		if e.private {
			prefix = "*"
		}
		if e.args != "" {
			fmt.Fprintf(&buf, "%s%s %s:\n", prefix, e.name, e.args)
		} else {
			fmt.Fprintf(&buf, "%s%s:\n", prefix, e.name)
		}
		if len(e.aliases) > 0 {
			fmt.Fprintf(&buf, "  aliases: %s\n", strings.Join(e.aliases, ", "))
		}
		for _, d := range e.desc {
			if d == "__SHELL_LIST__" {
				fmt.Fprintf(&buf, "  %s\n", randomShellList())
			} else {
				fmt.Fprintf(&buf, "  %s\n", d)
			}
		}
	}
	if private {
		buf.WriteString("* = private commands\n")
	}
	os.Stdout.Write(buf.Bytes())
	return 0
}

