	shell := "bash"
	path := ""
	if len(args) == 1 {
		path = args[0]
	} else if len(args) >= 2 {
		shell = args[0]
		path = args[1]
	}
	if path == "" {
		path = ".env"
	}
	data, err := os.ReadFile(path)
	if err != nil {
		logErr("%s", err.Error())
		return 1
	}
	pairs, err := parseDotenv(string(data))
	if err != nil {
		logErr("%s", err.Error())
		return 1
	}
	switch shell {
	case "bash", "zsh":
		for _, kv := range pairs {
			fmt.Printf("export %s=%s;\n", kv.k, bashEscape(kv.v))
		}
	case "fish":
		for _, kv := range pairs {
			fmt.Printf("set -x -g '%s' '%s';\n", kv.k, strings.ReplaceAll(kv.v, "'", "\\'"))
		}
	case "json":
		m := map[string]string{}
		for _, kv := range pairs {
			m[kv.k] = kv.v
		}
		b, _ := json.MarshalIndent(m, "", "  ")
		fmt.Println(string(b))
	default:
		logErr("unknown target shell '%s'", shell)
		return 1
	}
	return 0
}

