// parseDotenv parses a subset of the .env format.
func parseDotenv(s string) ([]kv, error) {
	var out []kv
	for _, line := range strings.Split(s, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		idx := strings.IndexByte(line, '=')
		if idx < 0 {
			continue
		}
		k := strings.TrimSpace(line[:idx])
		v := strings.TrimSpace(line[idx+1:])
		if len(v) >= 2 && (v[0] == '"' && v[len(v)-1] == '"') {
			v = v[1 : len(v)-1]
		} else if len(v) >= 2 && (v[0] == '\'' && v[len(v)-1] == '\'') {
			v = v[1 : len(v)-1]
		}
		out = append(out, kv{k: k, v: v})
	}
	sort.SliceStable(out, func(i, j int) bool { return false })
	return out, nil
}

type kv struct {
	k string
	v string
}

// bashEscape renders a value as a bash $'...' escaped string.
func bashEscape(s string) string {
	var b strings.Builder
	b.WriteString("$'")
	for _, r := range s {
		switch r {
		case '\\':
			b.WriteString("\\\\")
		case '\'':
			b.WriteString("\\'")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			b.WriteRune(r)
		}
	}
	b.WriteString("'")
	return b.String()
}
