// bashShellSafe reports whether s is a "safe" bare bash value (does not need
// any quoting). We use a conservative allow-list: [A-Za-z0-9_./+:@%-] or
// pure digits.
func bashShellSafe(s string) bool {
	if s == "" {
		return false
	}
	// All-digit -> safe
	allDigit := true
	for _, r := range s {
		if r < '0' || r > '9' {
			allDigit = false
			break
		}
	}
	if allDigit {
		return true
	}
	return false
}

// bashQuote renders a value for bash: returns $'...' for non-safe values.
func bashQuote(s string) string {
	if bashShellSafe(s) {
		return s
	}
	return bashEscape(s)
}

// fishQuote renders a value for fish shell.
func fishQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "\\'") + "'"
}

// DotenvCmdImpl parses .env and emits shell-specific export statements.
func DotenvCmdImpl(args []string) int {
	shell := "bash"
	path := ""
	if len(args) == 1 {
		shell = "bash"
		path = args[0]
		// If first arg is a known shell, treat as shell with default path.
		if shellIsDotenvKnown(path) {
			shell = path
			path = ".env"
		}
	} else if len(args) >= 2 {
		shell = args[0]
		path = args[1]
	}
	if path == "" {
		path = ".env"
	}
	data, err := os.ReadFile(path)
	if err != nil {
		logErr("%s", err.Error())
		return 1
	}
	pairs := parseDotenvPairs(string(data))
	var out strings.Builder
	switch shell {
	case "bash", "zsh":
		for _, kv := range pairs {
			fmt.Fprintf(&out, "export %s=%s;", kv.k, bashQuote(kv.v))
		}
		if out.Len() > 0 {
			out.WriteString("\n")
		}
	case "fish":
		for _, kv := range pairs {
			fmt.Fprintf(&out, "set -x -g '%s' %s;", kv.k, fishQuote(kv.v))
		}
		if out.Len() > 0 {
			out.WriteString("\n")
		}
	case "json":
		m := map[string]string{}
		for _, kv := range pairs {
			m[kv.k] = kv.v
		}
		b, _ := json.MarshalIndent(m, "", "  ")
		out.Write(b)
		out.WriteByte('\n')
	default:
		logErr("unknown target shell '%s'", shell)
		return 1
	}
	fmt.Print(out.String())
	return 0
}

func shellIsDotenvKnown(s string) bool {
	switch s {
	case "bash", "zsh", "fish", "json":
		return true
	}
	return false
}

func parseDotenvPairs(s string) []kv {
	var out []kv
	for _, line := range strings.Split(s, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		idx := strings.IndexByte(line, '=')
		if idx < 0 {
