package cli

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"time"
)

type fileRef struct {
	Path    string `json:"path"`
	Modtime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

// compressBase64URL returns the base64-URL-encoded zlib-compressed form of b.
func compressBase64URL(b []byte) string {
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	_, _ = w.Write(b)
	_ = w.Close()
	return base64.URLEncoding.EncodeToString(buf.Bytes())
}

func encodeWatches(refs []fileRef) string {
	if refs == nil {
		refs = []fileRef{}
	}
	b, _ := json.Marshal(refs)
	return compressBase64URL(b)
}

func emptyWatchesExport() string {
	return fmt.Sprintf("export DIRENV_WATCHES=$'%s';", encodeWatches(nil))
}

func watchesExport(paths []string) string {
	refs := make([]fileRef, 0, len(paths))
	for _, p := range paths {
		fi, err := os.Stat(p)
		if err != nil {
			refs = append(refs, fileRef{Path: p, Modtime: 0, Exists: false})
			continue
		}
		refs = append(refs, fileRef{Path: p, Modtime: fi.ModTime().Unix(), Exists: true})
	}
	return fmt.Sprintf("export DIRENV_WATCHES=$'%s';", encodeWatches(refs))
}

// Ensure `time` is referenced at least once to avoid unused-import errors
// if all call sites are commented out during development.
var _ = time.Unix
EOF

