package cli

import (
	"bufio"
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

// dumpEnv encodes the current environment as a compressed dump printed to
// stdout. An optional shell argument may be provided; the default format is
// the base64-encoded zlib-compressed JSON used by `direnv exec` internals.
func dumpEnv(args []string) int {
	m := map[string]string{}
	for _, kv := range os.Environ() {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			k := kv[:i]
			m[k] = kv[i+1:]
		}
	}
	b, _ := json.Marshal(m)
	enc := compressBase64URL(b)
	fmt.Println(enc)
	return 0
}

// applyDumpFile reads the file at path containing a gzenv-encoded dump and
// prints bash statements to apply the dump to the current environment.
func applyDumpFile(path string) int {
	data, err := os.ReadFile(path)
	if err != nil {
		logErr("%s", err.Error())
		return 1
	}
	return applyDumpBlob(strings.TrimSpace(string(data)))
}

func applyDumpBlob(blob string) int {
	raw, err := base64.URLEncoding.DecodeString(padB64(blob))
	if err != nil {
		logErr("unmarshal() base64 decoding: %s", err.Error())
		return 1
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		logErr("unmarshal() zlib opening: %s", err.Error())
		return 1
	}
	defer r.Close()
	decompressed, err := io.ReadAll(r)
	if err != nil {
		logErr("unmarshal() zlib decoding: %s", err.Error())
		return 1
	}
	var m map[string]*string
	if err := json.Unmarshal(decompressed, &m); err != nil {
		logErr("unmarshal() json: %s", err.Error())
		return 1
	}

	ignored := map[string]bool{
		"PWD": true, "SHLVL": true, "_": true,
		"DIRENV_IN_ENVRC": true,
	}

	// Build current env map
	cur := map[string]string{}
	for _, kv := range os.Environ() {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			cur[kv[:i]] = kv[i+1:]
		}
	}

	// Variables to unset: those in cur but not in target
	var unsets []string
	for k := range cur {
		if ignored[k] {
			continue
		}
		if _, ok := m[k]; !ok {
			unsets = append(unsets, k)
		}
	}
	sort.Strings(unsets)

	// Build output: order is: unsets first (map order), then sets
	var out strings.Builder
	for _, k := range unsets {
		fmt.Fprintf(&out, "unset %s;", k)
	}
	var keys []string
	for k := range m {
		if ignored[k] {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := m[k]
		if v == nil {
			fmt.Fprintf(&out, "unset %s;", k)
			continue
		}
		fmt.Fprintf(&out, "export %s=%s;", k, bashQuote(*v))
	}
	out.WriteString("\n")
	fmt.Print(out.String())
	return 0
}

func padB64(s string) string {
	if m := len(s) % 4; m != 0 {
		s += strings.Repeat("=", 4-m)
	}
	return s
}

// watchListFromStdin reads pairs of "mtime path" from stdin and emits the
// encoded DIRENV_WATCHES export statement.
func watchListFromStdin() string {
	var refs []fileRef
	sc := bufio.NewScanner(os.Stdin)
