		if err != nil {
			continue
		}
		p := strings.TrimSpace(line[i+1:])
		refs = append(refs, fileRef{Path: p, Modtime: mt, Exists: true})
	}
	if refs == nil {
		refs = []fileRef{}
	}
	return fmt.Sprintf("export DIRENV_WATCHES=$'%s';", encodeWatches(refs))
}

// currentCheck inspects the current file state against DIRENV_WATCHES to
// report "unknown", "has changed" or success.
func currentCheck(path string) int {
	watchesEnc := os.Getenv("DIRENV_WATCHES")
	if watchesEnc == "" {
		logErr("File %q is unknown", path)
		return 1
	}
	raw, err := base64.URLEncoding.DecodeString(padB64(watchesEnc))
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
