	decompressed, err := io.ReadAll(r)
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	var refs []fileRef
	if err := json.Unmarshal(decompressed, &refs); err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	for _, ref := range refs {
		if ref.Path == path {
			fi, err := os.Stat(path)
			if err != nil {
				if ref.Exists {
					logErr("File %q has changed", path)
					return 1
				}
				return 0
			}
			if !ref.Exists {
				logErr("File %q has changed", path)
				return 1
			}
			if fi.ModTime().Unix() != ref.Modtime {
				logErr("File %q has changed", path)
				return 1
			}
			return 0
		}
	}
	logErr("File %q is unknown", path)
	return 1
}
