	return applyDumpBlob(strings.TrimSpace(string(data)))
}

func applyDumpBlob(blob string) int {
	raw, err := base64.URLEncoding.DecodeString(padB64(blob))
	if err != nil {
		logErr("unmarshal() base64 decoding: %s", err.Error())
		return 1
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		logErr("unmarshal() zlib opening: %s", err.Error())
		return 1
	}
	defer r.Close()
	decompressed, err := io.ReadAll(r)
	if err != nil {
		logErr("unmarshal() zlib decoding: %s", err.Error())
		return 1
	}
	var m map[string]*string
	if err := json.Unmarshal(decompressed, &m); err != nil {
		logErr("unmarshal() json: %s", err.Error())
		return 1
	}

	ignored := map[string]bool{
		"PWD": true, "SHLVL": true, "_": true,
		"DIRENV_IN_ENVRC": true,
	}

	// Build current env map
	cur := map[string]string{}
	for _, kv := range os.Environ() {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			cur[kv[:i]] = kv[i+1:]
		}
	}

	// Variables to unset: those in cur but not in target
	var unsets []string
	for k := range cur {
		if ignored[k] {
			continue
		}
		if _, ok := m[k]; !ok {
			unsets = append(unsets, k)
		}
	}
	sort.Strings(unsets)

	// Build output: order is: unsets first (map order), then sets
	var out strings.Builder
	for _, k := range unsets {
		fmt.Fprintf(&out, "unset %s;", k)
	}
	var keys []string
	for k := range m {
		if ignored[k] {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		v := m[k]
		if v == nil {
			fmt.Fprintf(&out, "unset %s;", k)
			continue
		}
		fmt.Fprintf(&out, "export %s=%s;", k, bashQuote(*v))
	}
	out.WriteString("\n")
	fmt.Print(out.String())
	return 0
}

func padB64(s string) string {
	if m := len(s) % 4; m != 0 {
		s += strings.Repeat("=", 4-m)
	}
	return s
}

// watchListFromStdin reads pairs of "mtime path" from stdin and emits the
// encoded DIRENV_WATCHES export statement.
func watchListFromStdin() string {
	var refs []fileRef
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1024*1024), 10*1024*1024)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		i := strings.IndexByte(line, ' ')
		if i < 0 {
			continue
		}
		mt, err := strconv.ParseInt(strings.TrimSpace(line[:i]), 10, 64)
		if err != nil {
			continue
		}
		p := strings.TrimSpace(line[i+1:])
		refs = append(refs, fileRef{Path: p, Modtime: mt, Exists: true})
	}
	if refs == nil {
		refs = []fileRef{}
	}
	return fmt.Sprintf("export DIRENV_WATCHES=$'%s';", encodeWatches(refs))
}

// currentCheck inspects the current file state against DIRENV_WATCHES to
// report "unknown", "has changed" or success.
func currentCheck(path string) int {
	watchesEnc := os.Getenv("DIRENV_WATCHES")
	if watchesEnc == "" {
		logErr("File %q is unknown", path)
		return 1
	}
	raw, err := base64.URLEncoding.DecodeString(padB64(watchesEnc))
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	r, err := zlib.NewReader(bytes.NewReader(raw))
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	defer r.Close()
	decompressed, err := io.ReadAll(r)
	if err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	var refs []fileRef
	if err := json.Unmarshal(decompressed, &refs); err != nil {
		logErr("File %q is unknown", path)
		return 1
	}
	for _, ref := range refs {
		if ref.Path == path {
			fi, err := os.Stat(path)
			if err != nil {
				if ref.Exists {
					logErr("File %q has changed", path)
					return 1
				}
				return 0
			}
			if !ref.Exists {
				logErr("File %q has changed", path)
				return 1
			}
			if fi.ModTime().Unix() != ref.Modtime {
				logErr("File %q has changed", path)
				return 1
			}
			return 0
		}
	}
	logErr("File %q is unknown", path)
	return 1
}
